(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-990":{scenario:{company:"Thanh Lam Bulk Carriers",supervisor:{name:"Ngô Quốc Bảo",role:{vi:"Thuyền trưởng",en:"Master"}},ref_code:"PP-0931",title:{vi:"Đúng quy tắc tránh va. Đủ nước dưới ki. An toàn rồi mới đúng giờ.",en:"Right COLREG rule. Enough water under the keel. Safety before schedule."},brief:{vi:"Tàu hàng rời mô phỏng chuẩn bị vào luồng hẹp. Mớn nước tĩnh 11,6 m, Cb 0,80, tốc độ kế hoạch 8 hải lý/giờ; điểm nông nhất có độ sâu hải đồ 12,4 m, thủy triều dự báo 1,85 m. Trên radar, tàu B tiếp cận từ phương vị tương đối 125° mạn phải, nhanh hơn và đang rút ngắn khoảng cách. Bản nháp kế hoạch chuyến đi PP-0931 ghi tình huống RULE-15 và UKC 265 cm. Đối chiếu bản đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"A training bulk carrier is about to enter a confined channel. Static draft 11.6 m, Cb 0.80, planned speed 8 knots; the shallowest point has a charted depth of 12.4 m and a predicted tide of 1.85 m. On radar, vessel B approaches from a relative bearing of 125° to starboard, faster and closing. Draft passage plan PP-0931 records situation RULE-15 and a UKC of 265 cm. Compare it with the approved plan, correct both fields and write an evidence-based report."},reference_title:{vi:"Kế hoạch chuyến đi đã duyệt · PP-0931",en:"Approved passage plan · PP-0931"},fields:[{id:"COLREG_RULE",label:{vi:"Tình huống tránh va áp dụng",en:"Applicable collision rule"},initial:"RULE-15",expected:"RULE-13",choices:["RULE-13","RULE-14","RULE-15"],reference:"Bảng đánh giá tình huống tránh va",hint:{vi:"Tàu đến từ hướng quá 22,5° sau trục ngang mạn (phương vị tương đối lớn hơn 112,5°) là tàu vượt, không phải cắt hướng.",en:"A vessel coming from more than 22.5° abaft the beam (relative bearing above 112.5°) is overtaking, not crossing."}},{id:"UKC_CM",label:{vi:"Độ sâu dưới ki tại điểm nông (cm)",en:"Under-keel clearance at the shoal (cm)"},initial:"265",expected:"163",reference:"Bảng tính UKC đã duyệt",ref_value:{vi:"Độ sâu hải đồ 12,4 m; triều 1,85 m; mớn tĩnh 11,6 m; Cb 0,80; V = 8 hải lý/giờ; luồng hẹp",en:"Charted depth 12.4 m; tide 1.85 m; static draft 11.6 m; Cb 0.80; V = 8 knots; confined channel"},hint:{vi:"Bản nháp quên trừ squat: tàu chạy trong luồng hẹp bị chìm thêm và mức chìm tăng theo bình phương tốc độ.",en:"The draft forgot squat: a ship in a confined channel sinks further, rising with the square of speed."}}],sop32:{vi:"UKC = độ sâu hải đồ + chiều cao triều - mớn nước tĩnh - squat; squat trong luồng hẹp = Cb x V² ÷ 50 (m, V tính bằng hải lý/giờ, công thức kinh nghiệm Barrass); đổi ra cm, làm tròn đến cm.",en:"UKC = charted depth + height of tide - static draft - squat; squat in a confined channel = Cb x V² ÷ 50 (m, V in knots, Barrass rule of thumb); convert to cm and round to the nearest cm."},context:{label:"ECDIS / PP-0931",metrics:[{label:{vi:"Mớn nước tĩnh",en:"Static draft"},value:"11.6 m"},{label:{vi:"Độ sâu hải đồ + triều",en:"Charted depth + tide"},value:"12.4 m + 1.85 m"},{label:{vi:"Tốc độ kế hoạch",en:"Planned speed"},value:"8 kn"},{label:{vi:"UKC tối thiểu theo chính sách",en:"Policy minimum UKC"},value:"10% draft"}]},crisis:{vi:"Đại lý báo cầu bến chỉ giữ chỗ đến 18:00, trễ sẽ bị phạt. Thuyền trưởng nói: “Tăng lên 11 hải lý qua luồng cho kịp, khỏi tính lại UKC, triều đang lên mà.” Ở 11 hải lý squat tăng mạnh.",en:"The agent says the berth is held only until 18:00, with penalties if late. The master says: “Go to 11 knots through the channel, no need to recalculate UKC, the tide is rising.” At 11 knots squat rises sharply."},options:{safe:{vi:"Tính lại UKC ở 11 hải lý, báo thuyền trưởng bằng văn bản rằng UKC dưới mức chính sách, đề xuất giữ 8 hải lý hoặc chờ con nước sau; nếu vẫn bị ép, ghi nhật ký và báo DPA theo ISM.",en:"Recalculate UKC at 11 knots, tell the master in writing it falls below policy, propose holding 8 knots or waiting for the next tide; if still pressed, log it and inform the DPA under the ISM Code."},shortcut:{vi:"Tăng tốc lên 11 hải lý theo lệnh, không tính lại UKC để kịp cầu bến.",en:"Increase to 11 knots as ordered without recalculating UKC to make the berth."},wait:{vi:"Im lặng giữ ca trực, để hoa tiêu và thuyền trưởng tự lo.",en:"Keep quiet on watch and leave it to the pilot and the master."}},questions:{vi:["Vì sao tình huống với tàu B là RULE-13? Khi đó tàu mình và tàu B có nghĩa vụ gì?","Trình bày cách tính UKC có squat và rủi ro nếu tăng tốc lên 11 hải lý qua luồng hẹp."],en:["Why is the encounter with vessel B a RULE-13 case? What are our duties and vessel B's duties?","Explain how you calculated UKC including squat and the risk of increasing to 11 knots in the channel."]},hints:{vi:["So phương vị tương đối của tàu B với giới hạn 22,5° sau trục ngang mạn trên bảng đánh giá.","Tính squat theo SOP mục 3.2 trước, rồi trừ cùng mớn nước tĩnh khỏi độ sâu có triều.","Đọc lại SOP mục 4.2: mọi quyết định làm giảm biên an toàn phải được ghi nhận và báo cáo theo hệ thống quản lý an toàn."],en:["Compare vessel B's relative bearing with the 22.5° abaft the beam limit on the assessment sheet.","Work out squat per SOP 3.2 first, then subtract it with the static draft from the depth plus tide.","Re-read SOP 4.2: any decision that cuts the safety margin must be logged and reported through the safety management system."]}},learning:{summary:{vi:"Sĩ quan boong đảm nhiệm ca trực buồng lái, lập và theo dõi kế hoạch chuyến đi, xác định vị trí, tránh va, giám sát làm hàng, ổn định tàu và quản lý thiết bị cứu sinh, cứu hỏa. Nghề đòi hỏi nắm vững COLREG, SOLAS, STCW, thành thạo ECDIS, radar/ARPA, tính toán UKC, ổn định và kỷ luật báo cáo theo hệ thống quản lý an toàn, kể cả khi phải nói thẳng với cấp trên.",en:"A deck officer keeps the navigational watch, prepares and monitors the passage plan, fixes position, avoids collisions, supervises cargo work and stability and manages life-saving and fire-fighting equipment. The role demands mastery of COLREG, SOLAS and STCW, skill with ECDIS and radar/ARPA, UKC and stability calculations, and disciplined reporting through the safety management system, even when it means speaking up to superiors."},responsibilities:{vi:["Đứng ca buồng lái, duy trì cảnh giới, xác định vị trí và tránh va theo COLREG.","Lập kế hoạch chuyến đi từ bến đến bến: tuyến, điểm nông, UKC, thủy triều, cảnh báo hàng hải.","Giám sát làm hàng, mớn nước, ổn định và ứng suất thân tàu.","Bảo dưỡng thiết bị hàng hải, cứu sinh, cứu hỏa và tổ chức diễn tập.","Ghi nhật ký hàng hải, báo cáo sự cố và cận nguy theo hệ thống quản lý an toàn."],en:["Keep the bridge watch, maintain lookout, fix position and avoid collisions under COLREG.","Plan the voyage berth to berth: track, shoals, UKC, tides and navigational warnings.","Supervise cargo work, draft, stability and hull stresses.","Maintain navigation, life-saving and fire-fighting equipment and run drills.","Keep the logbook and report incidents and near misses through the safety management system."]},competencies:[{name:{vi:"Hành hải & tránh va",en:"Navigation & collision avoidance"},desc:{vi:"Đánh giá nguy cơ va chạm bằng phương vị, CPA, TCPA và áp dụng đúng quy tắc COLREG.",en:"Assess collision risk with bearings, CPA and TCPA and apply the correct COLREG rule."}},{name:{vi:"Lập kế hoạch chuyến đi",en:"Passage planning"},desc:{vi:"Thẩm định, lập kế hoạch, thực hiện và giám sát tuyến đi với biên an toàn rõ ràng.",en:"Appraise, plan, execute and monitor the passage with clear safety margins."}},{name:{vi:"Ổn định & làm hàng",en:"Stability & cargo"},desc:{vi:"Tính GM, mớn nước, ứng suất và theo dõi kế hoạch xếp dỡ an toàn.",en:"Compute GM, draft and stresses and monitor a safe loading plan."}},{name:{vi:"Quản lý nguồn lực buồng lái",en:"Bridge resource management"},desc:{vi:"Phối hợp với thuyền trưởng, hoa tiêu, thủy thủ và lên tiếng khi phát hiện rủi ro.",en:"Work with the master, pilot and crew and speak up when risks appear."}},{name:{vi:"An toàn & tuân thủ",en:"Safety & compliance"},desc:{vi:"Tuân thủ SMS, ghi nhật ký trung thực và báo cáo theo kênh ISM khi cần.",en:"Follow the SMS, keep honest logs and report through ISM channels when needed."}}],knowledge:{vi:["Quy tắc quốc tế phòng ngừa đâm va tàu thuyền trên biển (COLREG 1972).","Công ước SOLAS, chương V về an toàn hành hải và kế hoạch chuyến đi.","Công ước STCW về tiêu chuẩn huấn luyện, cấp chứng chỉ và trực ca.","Bộ luật ISM về quản lý an toàn và vai trò người phụ trách trên bờ (DPA).","Hướng dẫn lập kế hoạch chuyến đi của IMO theo Nghị quyết A.893(21).","Tính UKC, squat, ổn định tàu và hiệu chỉnh mớn nước theo tỷ trọng nước."],en:["International Regulations for Preventing Collisions at Sea (COLREG 1972).","SOLAS chapter V on safety of navigation and passage planning.","The STCW Convention on training, certification and watchkeeping.","The ISM Code on safety management and the role of the designated person ashore (DPA).","IMO guidelines for voyage planning, Resolution A.893(21).","UKC, squat and stability calculations and draft correction for water density."]},tools:["ECDIS","Radar/ARPA","Hệ thống nhận dạng tự động (AIS)","Máy đo sâu hồi âm","Phần mềm tính ổn định & tải trọng"],kpis:{vi:["Số cận nguy và sự cố hành hải trong chuyến (mục tiêu bằng 0).","Tỷ lệ kế hoạch chuyến đi được kiểm tra, phê duyệt trước khi khởi hành.","Số khiếm khuyết về hàng hải trong kiểm tra của chính quyền cảng (PSC).","Tỷ lệ diễn tập và bảo dưỡng thiết bị hoàn thành đúng kế hoạch."],en:["Navigational near misses and incidents per voyage (target zero).","Share of passage plans checked and approved before departure.","Navigation deficiencies found in port state control (PSC) inspections.","Share of drills and equipment maintenance completed on schedule."]},day:[{time:"04:00",vi:"Nhận ca 04-08, kiểm tra vị trí, radar, AIS và lệnh đêm của thuyền trưởng.",en:"Take the 04-08 watch and check position, radar, AIS and the master's night orders."},{time:"06:30",vi:"Đọc mớn nước, cập nhật thủy triều và tính UKC cho đoạn luồng vào cảng.",en:"Read drafts, update tides and calculate UKC for the port approach channel."},{time:"08:00",vi:"Bàn giao ca, cập nhật nhật ký hàng hải và báo cáo vị trí.",en:"Hand over the watch, update the logbook and send the position report."},{time:"14:00",vi:"Bảo dưỡng thiết bị cứu sinh, cứu hỏa và chuẩn bị diễn tập.",en:"Maintain life-saving and fire-fighting gear and prepare a drill."},{time:"16:00",vi:"Nhận ca 16-20, phối hợp hoa tiêu vào luồng và giám sát tàu thuyền xung quanh.",en:"Take the 16-20 watch, work with the pilot in the channel and monitor nearby traffic."}],mistakes:{vi:["Quên trừ squat hoặc dùng sai giờ thủy triều khi tính UKC.","Đánh giá nhầm tình huống vượt thành cắt hướng do không đo phương vị tương đối chính xác.","Giữ im lặng khi kế hoạch bị ép giảm biên an toàn, không ghi nhật ký và không báo cáo."],en:["Forgetting squat or using the wrong tide time when calculating UKC.","Mistaking overtaking for crossing by not measuring the relative bearing accurately.","Staying silent when the safety margin is cut, without logging or reporting it."]},career:[{vi:"Sĩ quan boong tập sự",en:"Deck cadet"},{vi:"Sĩ quan boong (phó ba, phó hai)",en:"Third or second officer"},{vi:"Đại phó",en:"Chief officer"},{vi:"Thuyền trưởng",en:"Master"}],glossary:[{term:"UKC",vi:"Độ sâu dưới ki: khoảng nước còn lại giữa đáy tàu và đáy luồng.",en:"Under-keel clearance: the water left between the keel and the seabed."},{term:"Squat",vi:"Hiện tượng tàu chìm thêm khi chạy do áp suất nước dưới thân tàu giảm, tăng theo tốc độ.",en:"Extra sinkage of a moving ship due to lower pressure under the hull, increasing with speed."},{term:"Stand-on vessel",vi:"Tàu được nhường đường, phải giữ hướng và tốc độ nhưng vẫn phải hành động khi tàu kia không tránh.",en:"Vessel that keeps course and speed but must act if the give-way vessel does not."},{term:"ECDIS",vi:"Hệ thống hiển thị hải đồ điện tử và thông tin, dùng để lập và theo dõi tuyến đi.",en:"Electronic chart display and information system for planning and monitoring the route."},{term:"DPA",vi:"Người phụ trách trên bờ theo Bộ luật ISM, có quyền tiếp cận lãnh đạo cao nhất của công ty.",en:"Designated person ashore under the ISM Code with direct access to top management."}],quiz:[{q:{vi:"Tàu khác tiến đến từ hướng quá 22,5° sau trục ngang mạn của tàu mình là tình huống nào?",en:"A vessel approaching from more than 22.5° abaft your beam creates which situation?"},options:{vi:["Đối hướng (Rule 14)","Cắt hướng (Rule 15)","Vượt (Rule 13)","Tầm nhìn hạn chế (Rule 19)"],en:["Head-on (Rule 14)","Crossing (Rule 15)","Overtaking (Rule 13)","Restricted visibility (Rule 19)"]},answer:2,explain:{vi:"Theo Rule 13, tàu đến từ hướng quá 22,5° sau trục ngang mạn là tàu vượt và phải tránh đường.",en:"Under Rule 13, a vessel coming from more than 22.5° abaft the beam is overtaking and must keep clear."}},{q:{vi:"Cb 0,75, tốc độ 10 hải lý/giờ trong luồng hẹp. Squat theo Cb x V² ÷ 50 là bao nhiêu?",en:"Cb 0.75 at 10 knots in a confined channel. What is squat by Cb x V² ÷ 50?"},options:{vi:["0,75 m","1,5 m","3,0 m","1,0 m"],en:["0.75 m","1.5 m","3.0 m","1.0 m"]},answer:1,explain:{vi:"Độ chìm squat = 0,75 x 100 ÷ 50 = 1,5 m.",en:"Squat = 0.75 x 100 ÷ 50 = 1.5 m."}},{q:{vi:"Thuyền trưởng yêu cầu tăng tốc qua luồng nông mà không tính lại UKC. Sĩ quan ca nên làm gì?",en:"The master orders a speed increase through a shallow channel without recalculating UKC. What should the officer of the watch do?"},options:{vi:["Làm theo vì thuyền trưởng quyết định","Tự giảm tốc mà không báo ai","Bỏ ca trực để phản đối","Tính lại UKC, báo cáo bằng văn bản, đề xuất phương án an toàn và ghi nhật ký"],en:["Comply because the master decides","Reduce speed without telling anyone","Leave the watch in protest","Recalculate UKC, report in writing, propose a safe option and log it"]},answer:3,explain:{vi:"Sĩ quan phải lên tiếng bằng số liệu, đề xuất phương án an toàn và ghi nhận để hệ thống ISM xử lý.",en:"The officer must speak up with data, propose a safe option and record it for the ISM system."}},{q:{vi:"Theo Bộ luật ISM, DPA là ai?",en:"Under the ISM Code, who is the DPA?"},options:{vi:["Người phụ trách trên bờ có quyền tiếp cận lãnh đạo cao nhất","Hoa tiêu dẫn tàu","Đại lý tàu tại cảng","Thanh tra chính quyền cảng"],en:["The shore-based person with access to top management","The harbour pilot","The port agent","The port state inspector"]},answer:0,explain:{vi:"DPA là cầu nối giữa tàu và lãnh đạo cao nhất, giám sát an toàn và tiếp nhận báo cáo của thuyền viên.",en:"The DPA links ship and top management, monitors safety and receives crew reports."}}],tools_en:["ECDIS","Radar/ARPA","Automatic Identification System (AIS)","Echo sounder","Loading and stability software"]}}})})(window.KKR);
